I have changed the code, and the problem no longer occurs; i.e., the
session message is no longer displayed when I toggle the coloring rules on
and off, and the multiple commands are displayed in the packet list.. This
is the change:

static uint16_t last_fnum = 0;
static bool mult_cmds = false;
static uint16_t current_pass_fnum = 0;


 if (!pinfo->fd->visited) {
        /* First pass: reset tracking for this frame */
        if (pinfo->fd->num != current_pass_fnum) {
           l ast_fnum = 0;
           mult_cmds = false;
           current_pass_fnum = pinfo->fd->num;
        }
}

if (pinfo->fd->num == last_fnum) {
   mult_cmds = true;
} else {
   mult_cmds = false;
   last_fnum = pinfo->fd->num;
}
If this code seems alright to you, I'll create a new MR
.

